order:
var value:i64[2]=[3,4];recursive fn later()->i64{value[0]=9;return 0;}
recursive fn read(a:i64[2],x:i64)->i64{return a[0]+x;}
fn main(){assert(read(value,later())==3);assert(value[0]==9);print("order");}

inline_order:
var value:i64[2]=[3,4];recursive fn later()->i64{value[0]=9;return 0;}
inline fn read(a:i64[2],x:i64)->i64{return a[0]+x;}
fn main(){assert(read(value,later())==3);assert(value[0]==9);print("inline_order");}

callback_order:
var value:i64[2]=[3,4];recursive fn later()->i64{value[0]=9;return 0;}
fn apply<F>()->i64{F(copy(value),later())}
fn main(){assert(apply(){a,x=>a[0]+x}==3);assert(value[0]==9);print("callback_order");}

data:
struct H{items:i64[2]}
recursive fn read(a:i64[2])->i64{a[0]=9;return a[1];}
fn main(){var rows:H[]=[H{items:[3,4]}];assert(read(rows[0].items)==4);assert(rows[0].items[0]==3);print("data");}

global:
var original:i64[2]=[3,4];recursive fn read(a:i64[2])->i64{return a[1];}
var result:i64=read(original);
fn main(){assert(result==4);print("global");}

nominal_result:
struct S{n:i64}
recursive fn make(a:i64[2])->S{return S{n:a[0]+a[1]};}
fn main(){var a:i64[2]=[3,4];var s:S=make(a);assert(s.n==7);print("nominal_result");}

later_return:
var value:i64[2]=[3,4];recursive fn use(a:i64[2],n:i64)->i64{return a[0]+n;}
recursive fn run(early:bool)->i64{return use(value,{if early{return 7;}3});}
fn main(){assert(run(true)==7);assert(run(false)==6);assert(value[0]==3);print("later_return");}
